                                hours: {
                                    start: string;
                                    end: string;
                                };
                                /** @description ISO 8601. */
                                start_at: string | null;
                                /** @description ISO 8601. */
                                end_at: string | null;
                                /** @description Email steps: the least minutes between two emails this Campaign sends from one Mailbox. Default 5; below 2 is warned (W20). */
                                min_email_gap_minutes: number;
